-- Módulo 45: documentos internos de transporte; no emisión fiscal.
CREATE TABLE "GuiasRemision" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Serie" varchar(8) NOT NULL CHECK ("Serie" ~ '^[A-Z0-9]{1,8}$'),
    "Numero" integer NOT NULL CHECK ("Numero" BETWEEN 1 AND 99999999),
    "Estado" varchar(10) NOT NULL DEFAULT 'Borrador',
    "FechaInicioTraslado" timestamptz NOT NULL,
    "RemitenteNombre" varchar(200) NOT NULL CHECK ("RemitenteNombre" = btrim("RemitenteNombre") AND length("RemitenteNombre") > 0),
    "RemitenteDocumento" varchar(20) NOT NULL CHECK ("RemitenteDocumento" = btrim("RemitenteDocumento") AND length("RemitenteDocumento") > 0),
    "DestinatarioNombre" varchar(200) NOT NULL CHECK ("DestinatarioNombre" = btrim("DestinatarioNombre") AND length("DestinatarioNombre") > 0),
    "DestinatarioDocumento" varchar(20) NOT NULL CHECK ("DestinatarioDocumento" = btrim("DestinatarioDocumento") AND length("DestinatarioDocumento") > 0),
    "DireccionOrigen" varchar(300) NOT NULL CHECK ("DireccionOrigen" = btrim("DireccionOrigen") AND length("DireccionOrigen") > 0),
    "DireccionDestino" varchar(300) NOT NULL CHECK ("DireccionDestino" = btrim("DireccionDestino") AND length("DireccionDestino") > 0),
    "MotivoTraslado" varchar(200) NOT NULL CHECK ("MotivoTraslado" = btrim("MotivoTraslado") AND length("MotivoTraslado") > 0),
    "Transportista" varchar(200) NOT NULL CHECK ("Transportista" = btrim("Transportista") AND length("Transportista") > 0),
    "Conductor" varchar(100) NOT NULL CHECK ("Conductor" = btrim("Conductor") AND length("Conductor") > 0),
    "Placa" varchar(20) NOT NULL CHECK ("Placa" = btrim("Placa") AND length("Placa") > 0),
    "PesoBrutoKg" numeric(12,2) NOT NULL CHECK ("PesoBrutoKg" BETWEEN 0.01 AND 9999999999.99),
    "Observaciones" varchar(500),
    "FechaEmision" timestamptz,
    "FechaAnulacion" timestamptz,
    "MotivoAnulacion" varchar(500),
    CONSTRAINT "CK_GuiasRemision_Estado" CHECK (
        ("Estado" = 'Borrador' AND "FechaEmision" IS NULL AND "FechaAnulacion" IS NULL AND "MotivoAnulacion" IS NULL) OR
        ("Estado" = 'Emitida' AND "FechaEmision" IS NOT NULL AND "FechaAnulacion" IS NULL AND "MotivoAnulacion" IS NULL) OR
        ("Estado" = 'Anulada' AND "FechaAnulacion" IS NOT NULL AND "MotivoAnulacion" IS NOT NULL AND length(btrim("MotivoAnulacion")) > 0))
);
CREATE UNIQUE INDEX "IX_GuiasRemision_Serie_Numero" ON "GuiasRemision" ("Serie", "Numero");
CREATE TABLE "LineasGuiaRemision" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "GuiaRemisionId" integer NOT NULL REFERENCES "GuiasRemision" ("Id") ON DELETE CASCADE,
    "Posicion" integer NOT NULL CHECK ("Posicion" BETWEEN 1 AND 100),
    "Sku" varchar(40) NOT NULL CHECK ("Sku" = btrim("Sku") AND length("Sku") > 0),
    "Descripcion" varchar(200) NOT NULL CHECK ("Descripcion" = btrim("Descripcion") AND length("Descripcion") > 0),
    "UnidadMedida" varchar(10) NOT NULL CHECK ("UnidadMedida" = btrim("UnidadMedida") AND length("UnidadMedida") > 0),
    "Cantidad" numeric(12,3) NOT NULL CHECK ("Cantidad" BETWEEN 0.001 AND 999999999.999)
);
CREATE INDEX "IX_LineasGuiaRemision_GuiaRemisionId" ON "LineasGuiaRemision" ("GuiaRemisionId");
